"""Master computation: all reported quantities at L1/L2/L3 for the final design."""
import numpy as np, json, math
from a2solve import *
from a2data import (DECK, ZONES, zone_area, SCENARIOS, CHORD_LINES, WALL_LINES,
                    H_DECK, panels, QH, q, BANDS, Cp, CHORD_SECT, CHORD_COST_PER_LB)
from piers import PIERS, pier_xy, Ec, Gc, H_DECK_IN
from collections import defaultdict

# final deck (config J)
DECK_CODE={'Z11':'D22-36/7-4','Z12':'D22-36/7-4','Z13':'D22-36/7-4',
           'Z21':'D22-36/4-4','Z22':'D22-36/4-4','Z23':'D22-36/7-4',
           'Z31':'D22-36/7-4','Z32':'D22-36/7-4','Z33':'D22-36/7-4',
           'Z41':'D22-36/7-4','Z42':'D22-36/4-4','Z43':'D22-36/7-4'}
def cap_asd(c): return DECK[c]['nominal_plf']/DECK[c]['omega_d']
def gp_used(z): return DECK[DECK_CODE[z]]['Gp_kip_per_in']*(1.15 if z=='Z22' else 1.0)
def cost_sf(c): return DECK[c]['cost_per_sf']

# chord sections (from iteration: PL3x3/8 all, except none needed bigger)
SECT_LIST=sorted(CHORD_SECT.keys(), key=lambda s: CHORD_SECT[s]['area_in2'])
def pick_section(max_t,max_c):
    for s in SECT_LIST:
        d=CHORD_SECT[s]
        if d['allowable_tension_kips']>=max_t-1e-6 and d['allowable_compression_kips']>=abs(max_c)-1e-6:
            return s
    return SECT_LIST[-1]

def compute(H, deck_code, chord_section):
    chord_area={cid:CHORD_SECT[chord_section[cid]]['area_in2'] for cid in CHORD_LINES}
    deck_gp={z:gp_used(z) for z in ZONES}
    m=build_mesh(H)
    zoneelem=defaultdict(list)
    for ei,e in enumerate(m.elems): zoneelem[m.cell_zone[ei]].append(ei)
    K,ndof=assemble_K(m,deck_gp,chord_area)
    res=solve(m,K,deck_gp,chord_area,SCENARIOS)
    out={'H':H,'elements':len(m.elems),'nodes':len(m.coords),'res':{},'zonemax':{},'max_unit_shear':0}
    # elements on each wall line (edge on the line)
    line_elems=defaultdict(list)
    for ei,e in enumerate(m.elems):
        co=m.coords[list(e)]
        xs=[c[0] for c in co]; ys=[c[1] for c in co]
